    const normalizedSurface =
      ensureNormalizedAddressSchemaSurface &&
      ensureNormalizedAddressSchemaSurface({ ...finalAddressChoice });
    const normalizedComplete =
      normalizedSurface &&
      hasCompleteNormalizedAddress({ ...normalizedSurface });

